// DISPOSABLE D3508/D3262 research. Observes earlier literal exact tables;
// never changes the frozen source reader, original capture, timing or admission.
import { readFileSync, writeFileSync } from "node:fs";
import { gunzipSync } from "node:zlib";
import { resolve } from "node:path";
import { fileURLToPath } from "node:url";
import { parseProbe } from "./cost-stockfish.mjs";
import { costCases, loadCostPlan, sha } from "./cost-contract.mjs";

const check = (v, m) => { if (!v) throw new Error(`D3508_TIMED_TABLE_AUDIT: ${m}`); };
const same = (a, b) => JSON.stringify(a) === JSON.stringify(b);
const boundRefusal = "Bound-only score cannot form coherent rank table";
const authority = "disposable_earlier_literal_frame_observation_not_source_admission_or_profile";
const sourceNames = ["cost-timed-table-audit.mjs", "cost-stockfish.mjs", "stockfish-coherent-table.mjs", "cost-contract.mjs"];

/** An earlier exact frame is an observation, NOT an admitted fallback receipt. */
export function auditTimedTable(operands, lines) {
  const result = { authority, inputDigest: sha(JSON.stringify({ operands, lines })),
    originalSourceAdmissionChanged: false, moveRecommendationLicensed: false,
    boundForDelimiterBestmoveLicensed: false, earlierExactFrame: null };
  try {
    parseProbe(operands, lines);
    return { ...result, original: { kind: "admitted_by_unchanged_reader" } };
  } catch (e) {
    result.original = { kind: "refused_by_unchanged_reader", reason: e.message };
  }
  // Missing delimiter, illegal PV, terminal continuation, unknown operands and
  // fixed-depth requests are never made available by this research hypothesis.
  if (result.original.reason !== boundRefusal || operands.budget !== "movetime100") return result;
  const scored = lines.flatMap((line, index) => {
    const depth = /^info .*\bdepth (\d+)\b/u.exec(line);
    return depth && /\bscore (?:cp|mate) -?\d+\b/u.test(line) && /\bpv /u.test(line)
      ? [{ index, depth: Number(depth[1]) }] : [];
  });
  const depths = [...new Set(scored.map(x => x.depth))].sort((a, b) => b - a);
  for (const depth of depths) {
    const end = scored.filter(x => x.depth === depth).at(-1).index;
    // Each view is an exact contiguous literal prefix plus the actual delimiter.
    // No per-rank filtering, score substitution, new PV or raw-capture rewrite.
    const prefix = [...lines.slice(0, end + 1), lines.at(-1)];
    let observed;
    try { observed = parseProbe(operands, prefix); } catch { continue; }
    if (observed.coherentDepth !== depth) continue;
    const rankLines = observed.entries.map(entry => {
      const indexes = scored.filter(x => x.index <= end && x.depth === depth
        && Number(/\bmultipv (\d+)\b/u.exec(lines[x.index])?.[1] ?? 1) === entry.rank);
      return indexes.at(-1).index;
    });
    result.earlierExactFrame = { coherentDepth: observed.coherentDepth,
      latestReportedDepth: depths[0], literalPrefixEnd: end, rankLineIndexes: rankLines,
      entries: observed.entries, scorePerspective: observed.scorePerspective,
      literalDelimiterBestmove: observed.bestmove,
      delimiterMatchesFrameRankOne: observed.bestmove === observed.entries[0].moveUci,
      status: "earlier_exact_literal_table_observed_not_admitted" };
    break;
  }
  return result;
}

export function auditRejectedGroups(metadataLiteral, groups) {
  const metadata = JSON.parse(metadataLiteral);
  const plan = loadCostPlan();
  check(Number.isSafeInteger(metadata.start) && metadata.start >= 0 && metadata.start % 3 === 0
    && Number.isSafeInteger(metadata.limit) && metadata.limit > 0 && metadata.limit % 3 === 0
    && metadata.start + metadata.limit <= plan.expectedCases
    && metadata.expectedCases === plan.expectedCases
    && metadata.planDigest === sha(`${JSON.stringify(plan, null, 2)}\n`)
    && same(metadata.cases, [...costCases(plan)].slice(metadata.start, metadata.start + metadata.limit)),
  "changed frozen batch population");
  check(metadata.question === "D3262" && metadata.cases?.length === metadata.limit
    && typeof metadata.planDigest === "string" && metadata.provider?.requested === true,
  "original batch metadata required");
  check(Array.isArray(groups) && groups.length > 0 && new Set(groups.map(x => x.name)).size === groups.length,
    "explicit unique original groups required");
  const examples = [];
  for (const group of groups) {
    check(/^triplet-\d{6}\.json\.gz$/u.test(group.name), "foreign group name");
    const bytes = Buffer.from(group.base64, "base64");
    check(sha(bytes) === group.digest, "changed original compressed group");
    const records = JSON.parse(gunzipSync(bytes));
    check(records.length === 3 && same(records.map(x => x.row.regime), ["cold", "warm", "provider_offline"]),
      "lost regime triplet");
    for (const record of records) {
      check(record.row.planDigest === metadata.planDigest
        && same(record.raw.cell, Object.fromEntries(["rootId", "candidateUci", "setting", "horizon", "regime"].map(k => [k, record.row[k]])))
        && metadata.cases.some(cell => same(cell, record.raw.cell))
        && sha(JSON.stringify(record.raw)) === record.row.rawCaptureDigest,
      "crossed original case or raw bytes");
      check(record.raw.dependencies.length === record.row.providerQueries.length, "lost dependency population");
      if (record.row.regime !== "cold") continue;
      for (const [index, dependency] of record.raw.dependencies.entries()) {
        const ledger = record.row.providerQueries[index];
        check(same(ledger.operands, dependency.operands) && ledger.state === dependency.state,
          "crossed query ledger");
        if (dependency.state !== "invalid" || dependency.failure !== boundRefusal) continue;
        const capture = dependency.rejectedCapture;
        check(record.row.kind === "invalid_source" && ledger.receiptDigest === null
          && dependency.receipt === null && same(capture?.operands, dependency.operands)
          && dependency.operands.provider === "stockfish"
          && dependency.operands.sourceDigest === metadata.provider.sourceDigest
          && dependency.operands.budget === "movetime100", "not a literal rejected timed query");
        const observation = auditTimedTable(capture.operands, capture.lines);
        check(observation.original.kind === "refused_by_unchanged_reader"
          && observation.original.reason === dependency.failure, "original refusal does not replay");
        examples.push({ group: group.name, case: record.raw.cell, dependencyIndex: index,
          originalFailure: dependency.failure, observation });
      }
    }
  }
  check(examples.length > 0, "no original bound-refused examples");
  return { question: "D3508", parentQuestion: "D3262", authority, examples,
    originalSourceAdmissionChanged: false, productionProfileSelected: false,
    wholePopulationClaim: false, clocksRepeated: false,
    sampling: "explicit_failure_examples_not_random_sample_or_complete_cost_population" };
}

export function checkTimedTableAudit(value) {
  check(value && value.version === 1 && typeof value.metadataLiteral === "string"
    && sha(value.metadataLiteral) === value.metadataDigest, "changed original metadata");
  check(Array.isArray(value.sourceSnapshots) && same(value.sourceSnapshots.map(x => x.name), sourceNames)
    && value.sourceSnapshots.every(x => typeof x.literal === "string" && sha(x.literal) === x.digest),
    "missing or changed auditor/reader sources");
  const metadata = JSON.parse(value.metadataLiteral);
  for (const source of value.sourceSnapshots.slice(1)) {
    check(metadata.instrumentDigests?.[source.name] === source.digest,
      "audit reader does not match captured reader");
  }
  check(same(value.result, auditRejectedGroups(value.metadataLiteral, value.groups)), "changed observed tables or scope");
  return { examples: value.result.examples.length,
    earlierExactFrames: value.result.examples.filter(x => x.observation.earlierExactFrame !== null).length,
    delimiterDisagreements: value.result.examples.filter(x => x.observation.earlierExactFrame?.delimiterMatchesFrameRankOne === false).length,
    authority, originalSourceAdmissionChanged: false };
}

if (process.argv[1] && resolve(process.argv[1]) === fileURLToPath(import.meta.url)) {
  const args = process.argv.slice(2);
  if (args.length === 2 && args[0] === "--check") {
    const bytes = readFileSync(args[1]);
    process.stdout.write(`${JSON.stringify({ ...checkTimedTableAudit(JSON.parse(bytes)), digest: sha(bytes) })}\n`);
  } else {
    check(args.length === 6 && args[0] === "--batch" && args[2] === "--groups" && args[4] === "--out",
      "use --check <file> or --batch <directory> --groups <CSV> --out <new-file>");
    const names = args[3].split(",");
    check(names.every(x => /^triplet-\d{6}\.json\.gz$/u.test(x)) && new Set(names).size === names.length,
      "explicit unique original group names required");
    const metadataLiteral = readFileSync(resolve(args[1], "metadata.json"), "utf8");
    const groups = names.map(name => {
      const bytes = readFileSync(resolve(args[1], name));
      return { name, digest: sha(bytes), base64: bytes.toString("base64") };
    });
    const sourceSnapshots = sourceNames.map(name => {
      const literal = readFileSync(new URL(name, import.meta.url), "utf8");
      return { name, digest: sha(literal), literal };
    });
    const value = { version: 1, metadataLiteral, metadataDigest: sha(metadataLiteral), groups,
      sourceSnapshots, result: auditRejectedGroups(metadataLiteral, groups) };
    const summary = checkTimedTableAudit(value), bytes = `${JSON.stringify(value, null, 2)}\n`;
    writeFileSync(args[5], bytes, { flag: "wx" });
    process.stdout.write(`${JSON.stringify({ ...summary, digest: sha(bytes) })}\n`);
  }
}

// Disposable D3262 live measurement source. Never imported by production.
import { spawn } from "node:child_process";
import { readFileSync } from "node:fs";
import { createInterface } from "node:readline";
import { Chess, normalizeMove } from "../../packages/runtime/node_modules/chessops/dist/esm/chess.js";
import { makeFen, parseFen } from "../../packages/runtime/node_modules/chessops/dist/esm/fen.js";
import { makeUci, parseUci } from "../../packages/runtime/node_modules/chessops/dist/esm/util.js";
import { legalMoves } from "./exact-reply-enumeration.mjs";
import { selectCoherentTopEntries } from "./stockfish-coherent-table.mjs";
import { queryIdentity, sha } from "./cost-contract.mjs";

export const position = fen => Chess.fromSetup(parseFen(fen).unwrap()).unwrap();
export function replay(fen, history) {
  const pos = position(fen);
  for (const uci of history) {
    if (terminal(pos) !== null) throw new Error("Continuation after absorbing terminal");
    const entry = legalMoves(pos).find(x => x.uci === uci);
    if (!entry) throw new Error(`Illegal/noncanonical history: ${uci}`);
    pos.play(entry.move);
  }
  return pos;
}
export const fenOf = pos => makeFen(pos.toSetup());
export function terminal(pos) {
  if (legalMoves(pos).length === 0) return pos.isCheck() ? "CHECKMATE" : "STALEMATE";
  if (pos.isInsufficientMaterial()) return "INSUFFICIENT_MATERIAL";
  return pos.halfmoves >= 150 ? "SEVENTYFIVE_MOVES" : null;
}
function canonicalPv(fen, raw) {
  const pos = position(fen), history = [];
  for (const uci of raw) {
    if (terminal(pos) !== null) throw new Error("Provider PV continued beyond terminal");
    const parsed = parseUci(uci), move = parsed && normalizeMove(pos, parsed);
    if (!move || !pos.isLegal(move)) throw new Error("Illegal provider PV");
    const entry = legalMoves(pos).find(x => makeUci(x.move) === makeUci(move));
    if (!entry) throw new Error("Provider move absent from exact population");
    history.push(entry.uci); pos.play(move);
  }
  return history;
}

/** Reparse literal UCI, validate all scored PVs, retain one depth-complete table. */
export function parseProbe(operands, lines) {
  queryIdentity(operands);
  const legal = legalMoves(position(operands.fen)).map(x => x.uci);
  if (terminal(position(operands.fen)) !== null) throw new Error("Terminal should not query provider");
  const count = Math.min(operands.multiPv, legal.length), parsed = [];
  if (!Array.isArray(lines) || !lines.at(-1)?.startsWith("bestmove ")) throw new Error("Missing bestmove delimiter");
  const best = lines.at(-1).split(/\s+/u)[1];
  if (!best || canonicalPv(operands.fen, [best]).length !== 1) throw new Error("Invalid bestmove");
  for (const line of lines.slice(0, -1)) {
    if (line.startsWith("bestmove ")) throw new Error("Multiple bestmove delimiters");
    const score = /\bscore (cp|mate) (-?\d+)\b/u.exec(line);
    const raw = /\bpv ((?:[a-h][1-8][a-h][1-8][qrbn]?(?:\s+|$))+)/u.exec(line)?.[1]?.trim().split(/\s+/u);
    if (!line.startsWith("info ") || !score || !raw) continue;
    const depth = Number(/\bdepth (\d+)\b/u.exec(line)?.[1] ?? 0);
    const rank = Number(/\bmultipv (\d+)\b/u.exec(line)?.[1] ?? 1);
    if (depth < 1 || rank < 1 || rank > count) throw new Error("Invalid scored rank/depth");
    const pv = canonicalPv(operands.fen, raw);
    parsed.push({ moveUci: pv[0], rank, depth, score: { kind: score[1], value: Number(score[2]),
      bound: /\b(?:lowerbound|upperbound)\b/u.test(line) }, pv, rawPv: raw });
  }
  const table = selectCoherentTopEntries(parsed, count);
  if (table.entries.some(x => x.score.bound)) throw new Error("Bound-only score cannot form coherent rank table");
  if (operands.budget.startsWith("depth") && table.coherentDepth !== Number(operands.budget.slice(5)))
    throw new Error("Incomplete requested depth; do not silently downgrade budget");
  return { legal, ...table, bestmove: canonicalPv(operands.fen, [best])[0],
    scorePerspective: "side_to_move", authority: "provider_search_not_engine_causality" };
}

export class SourceFailure extends Error {
  constructor(state, message) { super(message); this.state = state; }
}

export class CostStockfish {
  constructor(command, { args = [], timeoutMs = 60_000 } = {}) {
    if (!command || !Number.isSafeInteger(timeoutMs) || timeoutMs < 1) throw new Error("Executable/deadline required");
    this.sourceDigest = sha(JSON.stringify({ executableDigest: sha(readFileSync(command)), args,
      threads: 1, hashMb: 16, chess960: false, clearHashPerQuery: true }));
    this.timeoutMs = timeoutMs; this.command = command; this.queue = []; this.waiter = null;
    this.stderr = ""; this.failure = null; this.closed = false; this.busy = false;
    this.started = performance.now();
    this.child = spawn(command, args, { stdio: ["pipe", "pipe", "pipe"] });
    createInterface({ input: this.child.stdout }).on("line", line => {
      if (this.waiter) { const waiter = this.waiter; this.waiter = null; waiter.resolve(line); }
      else this.queue.push(line);
    });
    this.child.stderr.on("data", b => { this.stderr = (this.stderr + b).slice(-65536); });
    this.child.on("error", e => this.fail(new SourceFailure("unavailable", e.message)));
    this.child.stdin.on("error", e => this.fail(new SourceFailure("unavailable", e.message)));
    this.child.on("exit", (code, signal) => {
      if (!this.closed) this.fail(new SourceFailure("unavailable", `Early UCI exit: ${code}/${signal}`));
    });
  }
  fail(e) { this.failure = e; if (this.waiter) { this.waiter.reject(e); this.waiter = null; } }
  send(line) { if (this.failure) throw this.failure; this.child.stdin.write(`${line}\n`); }
  async until(predicate, deadline) {
    const lines = []; let bytes = 0;
    for (;;) {
      if (this.failure) throw this.failure;
      const remaining = deadline - performance.now();
      if (remaining <= 0) { const e = new SourceFailure("timed_out", "UCI operation deadline"); this.fail(e); this.child.kill(); throw e; }
      const line = this.queue.length ? this.queue.shift() : await new Promise((resolve, reject) => {
        const timer = setTimeout(() => {
          const e = new SourceFailure("timed_out", "UCI operation deadline");
          this.fail(e); this.child.kill();
        }, remaining);
        this.waiter = { resolve: x => { clearTimeout(timer); resolve(x); }, reject: e => { clearTimeout(timer); reject(e); } };
      });
      lines.push(line); bytes += Buffer.byteLength(line);
      if (bytes > 16 * 1024 * 1024) {
        const e = new SourceFailure("invalid", "UCI output exceeded retained capture bound");
        this.fail(e); this.child.kill(); throw e;
      }
      if (predicate(line)) return lines;
    }
  }
  async initialize() {
    const deadline = performance.now() + this.timeoutMs;
    this.send("uci"); const hello = await this.until(x => x === "uciok", deadline);
    this.engineName = hello.find(x => x.startsWith("id name "))?.slice(8);
    if (!this.engineName) throw new SourceFailure("invalid", "Missing engine identity");
    this.send("setoption name Threads value 1"); this.send("setoption name Hash value 16");
    this.send("setoption name UCI_Chess960 value false"); this.send("isready");
    await this.until(x => x === "readyok", deadline);
    this.startupMs = performance.now() - this.started;
    return this;
  }
  async execute(operands) {
    if (this.busy) throw new SourceFailure("invalid", "Parallel use of serialized UCI source");
    queryIdentity(operands);
    if (operands.sourceDigest !== this.sourceDigest) throw new SourceFailure("invalid", "Crossed binary/config identity");
    this.busy = true;
    const started = performance.now(), deadline = started + this.timeoutMs;
    try {
      const legal = legalMoves(position(operands.fen)).map(x => x.uci);
      this.send("ucinewgame"); this.send("setoption name Clear Hash");
      this.send(`setoption name MultiPV value ${Math.min(operands.multiPv, legal.length)}`);
      this.send("isready"); await this.until(x => x === "readyok", deadline);
      this.send(`position fen ${operands.fen}`);
      const go = operands.budget === "movetime100" ? "go movetime 100" : `go depth ${operands.budget.slice(5)}`;
      this.send(`${go} searchmoves ${legal.join(" ")}`);
      const lines = await this.until(x => x.startsWith("bestmove "), deadline);
      let result;
      try { result = parseProbe(operands, lines); }
      catch (e) { const failure = new SourceFailure("invalid", e.message); failure.capture = { operands, lines }; throw failure; }
      return { operands, engineName: this.engineName, started, ended: performance.now(), lines, result };
    } finally { this.busy = false; }
  }
  async close() {
    if (this.closed) return;
    this.closed = true;
    const exited = new Promise(resolve => this.child.once("exit", resolve));
    if (this.child.exitCode === null && this.child.signalCode === null) {
      if (!this.child.killed) this.child.stdin.end("quit\n");
      const timer = setTimeout(() => this.child.kill("SIGKILL"), 1000);
      await exited; clearTimeout(timer);
    }
  }
}

/** Dependencies only: warm cache is populated by the matching cold operation. */
export class CostDependencies {
  constructor(adapter, regime, initial = new Map()) {
    if (!["cold", "warm", "provider_offline"].includes(regime) || regime !== "warm" && initial.size)
      throw new Error("Cold/offline cache contamination");
    this.adapter = adapter; this.regime = regime; this.cache = new Map(initial);
    this.initialCacheEntries = initial.size; this.ledger = []; this.raw = []; this.seen = new Map(); this.sourceMs = 0;
  }
  async query(operands) {
    const identity = queryIdentity(operands);
    if (this.seen.has(identity)) return this.seen.get(identity);
    const started = performance.now(); let receipt, state, failure, rejectedCapture;
    if (this.regime === "provider_offline") { state = "unavailable"; failure = "Deliberately denied provider execution"; }
    else if (this.cache.has(identity)) { state = "cached"; receipt = this.cache.get(identity); }
    else if (this.regime === "warm") { state = "unavailable"; failure = "matching cold receipt unavailable; fresh execution is not warm"; }
    else {
      try { receipt = await this.adapter.execute(operands); state = "executed"; }
      catch (e) { if (!(e instanceof SourceFailure)) throw e; state = e.state; failure = e.message; rejectedCapture = e.capture; }
    }
    if (receipt) {
      try {
        if (queryIdentity(receipt.operands) !== identity
          || JSON.stringify((this.adapter.admitReceipt ?? parseProbe)(operands, receipt.lines)) !== JSON.stringify(receipt.result))
          throw new Error("Crossed dependency receipt/literal provider result");
      } catch (e) { state = "invalid"; failure = e.message; rejectedCapture = receipt; receipt = undefined; }
    }
    const elapsedMs = performance.now() - started, receiptDigest = receipt ? sha(JSON.stringify(receipt)) : null;
    this.sourceMs += elapsedMs;
    this.ledger.push({ operands, state, elapsedMs, receiptDigest });
    this.raw.push({ operands, state, receipt: receipt ?? null, failure: failure ?? null, rejectedCapture: rejectedCapture ?? null });
    if (state === "executed") this.cache.set(identity, receipt);
    const result = { state, result: receipt?.result ?? null };
    this.seen.set(identity, result); return result;
  }
}

// A MultiPV frame is one depth-complete rank table, not the newest info line
// observed independently for each move.
export function selectCoherentTopEntries(parsed, count) {
  if (!Number.isSafeInteger(count) || count < 1) throw new Error("Invalid coherent rank count");
  const reportedDepths = [...new Set(parsed.map((entry) => entry.depth))].sort((left, right) => right - left);
  for (const depth of reportedDepths) {
    const byRank = new Map(parsed.filter((entry) => entry.depth === depth && entry.rank <= count).map((entry) => [entry.rank, entry]));
    const entries = Array.from({ length: count }, (_, index) => byRank.get(index + 1));
    if (entries.some((entry) => entry === undefined) || new Set(entries.map((entry) => entry.moveUci)).size !== count) continue;
    return { entries, coherentDepth: depth, trailingPartialDepth: reportedDepths[0] > depth ? reportedDepths[0] : null };
  }
  throw new Error(`Stockfish returned no complete coherent ${count}-rank depth table`);
}

